import{_ as a,C as i,o,c as r,j as t,a as s,E as h,a6 as d}from"./chunks/framework.CCKCzdWs.js";const y=JSON.parse('{"title":"Piwi Runner","description":"Piwi Runner takes Run on my machine requests from a team instance without the dashboard: where to get it, how it installs beside the desktop app, and how it stays in the tray.","frontmatter":{"title":"Piwi Runner","description":"Piwi Runner takes Run on my machine requests from a team instance without the dashboard: where to get it, how it installs beside the desktop app, and how it stays in the tray.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/piwi-runner.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/piwi-runner.html"}],["meta",{"property":"og:title","content":"Piwi Runner | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Piwi Runner takes Run on my machine requests from a team instance without the dashboard: where to get it, how it installs beside the desktop app, and how it stays in the tray."}]]},"headers":[],"relativePath":"features/piwi-runner.md","filePath":"features/piwi-runner.md","lastUpdated":1794490413000}'),l={name:"features/piwi-runner.md"};function c(p,e,u,w,m,g){const n=i("Needs");return o(),r("div",null,[e[0]||(e[0]=t("h1",{id:"piwi-runner",tabindex:"-1"},[s("Piwi Runner "),t("a",{class:"header-anchor",href:"#piwi-runner","aria-label":'Permalink to "Piwi Runner"'},"​")],-1)),h(n,{admin:""}),e[1]||(e[1]=d('<p>Piwi Runner takes <a href="./run-on-my-machine.html">Run on my machine</a> requests from one team instance, without the dashboard: one window for the connection, the confirmation of each request and the runs it started. It is for a machine that only runs what the instance asks, where the <a href="./desktop.html">desktop app</a> and its local dashboard are more than needed. It keeps no database and serves no dashboard.</p><h2 id="where-it-is" tabindex="-1">Where it is <a class="header-anchor" href="#where-it-is" aria-label="Permalink to &quot;Where it is&quot;">​</a></h2><p>Download the installer from the <a href="https://github.com/PiwiTests/piwi/releases/latest" target="_blank" rel="noreferrer">latest release</a>, the files named <code>Piwi-Runner_…</code>:</p><table tabindex="0"><thead><tr><th>OS</th><th>Installer</th></tr></thead><tbody><tr><td><strong>Windows</strong></td><td><code>.exe</code> (per-user, no admin) or <code>.msi</code> (per-machine)</td></tr><tr><td><strong>macOS</strong> 13.5+ (Apple silicon)</td><td><code>.dmg</code></td></tr><tr><td><strong>Linux</strong> (x86-64)</td><td><code>.AppImage</code>, <code>.deb</code> or <code>.rpm</code>, each needing a system WebKitGTK (<code>webkit2gtk-4.1</code>)</td></tr></tbody></table><p>The installers are <strong>unsigned</strong>: on macOS, open the app once, then <strong>Open Anyway</strong> in <strong>Privacy &amp; Security</strong>; on Windows, <strong>More info</strong> then <strong>Run anyway</strong> in SmartScreen. Piwi Runner has no in-app updates yet: install a new version over the old one, which keeps your connection and linked folders.</p><h2 id="beside-the-desktop-app" tabindex="-1">Beside the desktop app <a class="header-anchor" href="#beside-the-desktop-app" aria-label="Permalink to &quot;Beside the desktop app&quot;">​</a></h2><p>Piwi Runner and the desktop app install side by side, and neither installer replaces the other: each has its own name, install folder, Linux package, settings, linked folders and keychain entry. Connected to the same instance, both are listed in <strong>Connected apps</strong>, and a request goes to the one you pick on the page.</p><h2 id="connect-it" tabindex="-1">Connect it <a class="header-anchor" href="#connect-it" aria-label="Permalink to &quot;Connect it&quot;">​</a></h2><p>Its window connects to an instance the way the desktop app does: enter the instance&#39;s address and click <strong>Connect</strong>, then allow <strong>Piwi Runner</strong> on the instance&#39;s page with the code the window shows. Its key stays in the operating system&#39;s keychain. Each project&#39;s folder is linked on the first request for it. The rest, from the confirmation to <strong>Stop</strong>, is described in <a href="./run-on-my-machine.html#in-the-app">Run on my machine</a>.</p><h2 id="in-the-tray" tabindex="-1">In the tray <a class="header-anchor" href="#in-the-tray" aria-label="Permalink to &quot;In the tray&quot;">​</a></h2><p>Closing the window leaves Piwi Runner in the tray, still connected, so the instance can reach it; a request brings the window forward. The tray menu has:</p><ul><li><strong>Open Piwi Runner</strong> (a click on the icon does the same) and <strong>Show logs</strong>;</li><li><strong>Run in background</strong>, on by default: turned off, closing the window quits the app, once you agree to stop the runs still going;</li><li><strong>Start on login</strong>, which launches it in the tray when you sign in;</li><li><strong>Quit Piwi Runner</strong>, which stops its runs, after asking.</li></ul><p>Its icon is the Piwi mark on a teal tile with a play sign, so it reads apart from the desktop app&#39;s in the tray and the taskbar.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./run-on-my-machine.html">Run on my machine</a>: who may ask, how an administrator turns it on, and what a request holds</li><li><a href="./desktop.html">Desktop app</a>: the other app that takes requests, with a local dashboard</li></ul>',15))])}const k=a(l,[["render",c]]);export{y as __pageData,k as default};
